"""model_factory.py  --  gives the app a LangChain chat model.   >>> YOU DO NOT EDIT THIS FILE <<<

Providers, in the order "Auto" tries them:
   1. AWS Bedrock   small Amazon Nova model (BEDROCK_SMALL_MODEL_ID in the course .env)        MAIN
   2. Azure Foundry AZURE_OPENAI_API_KEY + AZURE_OPENAI_ENDPOINT + AZURE_OPENAI_CHAT_DEPLOYMENTS  OPTIONAL
   3. OpenAI        OPENAI_API_KEY                                                             BACKUP
   4. Offline       no keys: a tiny rule-based stand-in so the lab still runs                  LAST RESORT
The app sidebar lets you pick one. The keys come from the course .env (the Participants / dxc-agentic-ai folder).
"""
import json
import os
import re
import sys
import time
from pathlib import Path
from urllib.parse import urlparse

try:
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
except Exception:
    pass

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]                              # the course folder (C:\AskIT\dxc-agentic-ai) where .env lives
for p in (str(ROOT), str(HERE)):
    if p not in sys.path:
        sys.path.insert(0, p)

from dotenv import dotenv_values                    # noqa: E402

for _env in [d / ".env" for d in reversed(HERE.parents) if (d / ".env").is_file()] + [HERE / ".env"]:
    if _env.is_file():                              # course .env first, a lab .env (if any) wins; empty values never win
        for _k, _v in dotenv_values(_env).items():
            if _v:
                os.environ[_k] = _v

from langchain_core.language_models.chat_models import BaseChatModel                 # noqa: E402
from langchain_core.messages import AIMessage, HumanMessage, SystemMessage, ToolMessage   # noqa: E402
from langchain_core.outputs import ChatGeneration, ChatResult                        # noqa: E402

# Approximate list prices in US$ per 1 million tokens (input, output). Check the provider's pricing page before quoting a client.
PRICES = {
    "bedrock": (0.035, 0.14),     # Amazon Nova Micro (on-demand, us-east-1)
    "azure": (0.25, 2.00),        # gpt-5.4-mini class (approx.); check your Azure pricing
    "openai": (0.25, 2.00),       # gpt-5-mini class
    "offline": (0.035, 0.14),     # pretend Nova Micro prices so the cost charts still mean something
}
LABELS = {"bedrock": "AWS Bedrock", "azure": "Azure AI Foundry", "openai": "OpenAI", "offline": "Offline stand-in"}


# ------------------------------------------------------------------------------------------------ which providers are ready
def status():
    """{provider: (ready, reason)} for the sidebar."""
    out = {}
    try:
        import boto3
        model = os.getenv("BEDROCK_SMALL_MODEL_ID", "")
        if not model or model == "REPLACE_ME":
            out["bedrock"] = (False, "BEDROCK_SMALL_MODEL_ID missing in .env")
        elif boto3.Session().get_credentials() is None:
            out["bedrock"] = (False, "AWS keys missing in .env")
        else:
            out["bedrock"] = (True, model)
    except Exception as e:
        out["bedrock"] = (False, f"boto3 problem: {e}")
    az_ok = bool(os.getenv("AZURE_OPENAI_API_KEY") and os.getenv("AZURE_OPENAI_ENDPOINT", "").startswith("http")
                 and "<" not in os.getenv("AZURE_OPENAI_ENDPOINT", "") and _azure_deployment())
    out["azure"] = (az_ok, _azure_deployment() if az_ok else "Azure keys not set in .env")
    out["openai"] = (bool(os.getenv("OPENAI_API_KEY")), os.getenv("OPENAI_MODEL", "gpt-5-mini") if os.getenv("OPENAI_API_KEY") else "OPENAI_API_KEY not set")
    out["offline"] = (True, "rule-based stand-in, no AI")
    return out


def auto_provider():
    forced = os.getenv("ASKIT_MODEL", "").strip().lower()
    if forced in LABELS:
        return forced
    st = status()
    return next(p for p in ("bedrock", "azure", "openai", "offline") if st[p][0])


AZURE_DEFAULT = "gpt-5.4-mini-1"          # the course-wide Azure chat deployment


def _azure_deployment():
    """Always gpt-5.4-mini-1, unless AZURE_OPENAI_CHAT_DEPLOYMENT (single name) is set in .env to override it."""
    return os.getenv("AZURE_OPENAI_CHAT_DEPLOYMENT", "").strip() or AZURE_DEFAULT


def get_model(provider=None):
    """Return a LangChain chat model for the provider (None = Auto)."""
    name = provider or auto_provider()
    if name == "bedrock":
        from botocore.config import Config
        from langchain_aws import ChatBedrockConverse
        return ChatBedrockConverse(model=os.getenv("BEDROCK_SMALL_MODEL_ID"), region_name=os.getenv("AWS_REGION", "us-east-1"),
                                   temperature=0, max_tokens=700,
                                   config=Config(retries={"max_attempts": 8, "mode": "adaptive"}, read_timeout=120))
    if name == "azure":
        from langchain_openai import ChatOpenAI
        u = urlparse(os.getenv("AZURE_OPENAI_ENDPOINT").strip())
        key = os.getenv("AZURE_OPENAI_API_KEY")
        return ChatOpenAI(model=_azure_deployment(), base_url=f"{u.scheme}://{u.netloc}/openai/v1", api_key=key,
                          default_headers={"api-key": key}, max_retries=4)
    if name == "openai":
        from langchain_openai import ChatOpenAI
        return ChatOpenAI(model=os.getenv("OPENAI_MODEL", "gpt-5-mini"), max_retries=4)
    return OfflineChatModel()


def model_label(provider):
    return f"{LABELS[provider]} · {status()[provider][1]}"


def cost_usd(provider, tokens_in, tokens_out):
    p_in, p_out = PRICES.get(provider, PRICES["bedrock"])
    return tokens_in / 1e6 * p_in + tokens_out / 1e6 * p_out


def text_of(message):
    """Plain text of a LangChain message (content can be a string or a list of blocks)."""
    c = getattr(message, "content", message)
    if isinstance(c, str):
        return c
    return "".join(b.get("text", "") for b in c if isinstance(b, dict))


def approx_tokens(text):
    return max(1, len(text) // 4)


# ------------------------------------------------------------------------------------------------ offline stand-in
class OfflineChatModel(BaseChatModel):
    """NOT a real model: a few if-statements that behave like one, so the lab runs with no keys."""

    @property
    def _llm_type(self):
        return "askit-offline"

    def bind_tools(self, tools, **kwargs):
        names = [getattr(t, "name", None) or getattr(t, "__name__", "") for t in tools]
        return OfflineChatModel(tool_names=names)

    tool_names: list = []

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):
        reply = self._reply(messages)
        n_in = sum(approx_tokens(text_of(m)) for m in messages)
        reply.usage_metadata = {"input_tokens": n_in, "output_tokens": approx_tokens(text_of(reply) or "tool call"),
                                "total_tokens": n_in + approx_tokens(text_of(reply) or "tool call")}
        time.sleep(0.15)
        return ChatResult(generations=[ChatGeneration(message=reply)])

    def _reply(self, messages):
        last = messages[-1]
        first = text_of(messages[0])
        if "Context Extraction Assistant" in text_of(last) or "Context Extraction Assistant" in first:
            return AIMessage(content=_offline_summary(text_of(last)))
        if "ONE word" in first and "Network" in first:                      # the Lab 8 router
            return AIMessage(content=_offline_route(text_of(last)))
        n = len(messages)
        if isinstance(last, ToolMessage):
            return AIMessage(content=_summary(last.name, _as_dict(last.content)))
        human = [m for m in messages if isinstance(m, HumanMessage)]
        q = text_of(human[-1]) if human else ""
        ql = q.lower()
        tools = set(self.tool_names)
        user = re.search(r"EMP-\d+", q, re.I)
        ticket = re.search(r"TKT-\d+", q, re.I)
        if "save_note" in tools and any(w in ql for w in ("remember", "my laptop is", "i use", "note that")):
            return _call("save_note", {"text": q.strip()}, n)
        if "recall_notes" in tools and any(w in ql for w in ("which laptop", "do you remember", "what do you know about me", "earlier chat")):
            return _call("recall_notes", {}, n)
        if "reset_password" in tools and "reset" in ql and user:
            return _call("reset_password", {"user_id": user.group(0).upper()}, n)
        if "get_ticket" in tools and ticket:
            return _call("get_ticket", {"ticket_id": ticket.group(0).upper()}, n)
        if len(human) > 1 and any(w in ql for w in ("summarise", "summarize", "first", "employee id", "my id")):
            return AIMessage(content=_from_history(messages, ql))
        if "search_kb" in tools:
            return _call("search_kb", {"query": q[:120]}, n)
        return AIMessage(content="(offline) I would answer this with a real model.")


def _call(name, args, n):
    return AIMessage(content="", tool_calls=[{"name": name, "args": args, "id": f"off{n}", "type": "tool_call"}])


def _as_dict(content):
    try:
        data = json.loads(content) if isinstance(content, str) else content
        return data if isinstance(data, dict) else {"result": data}
    except Exception:
        return {"result": str(content)}


def _summary(tool_name, data):
    if "error" in data:
        return "Sorry, that did not work: " + str(data["error"])
    if tool_name == "recall_notes":
        notes = data.get("result") or []
        return ("From earlier chats I know: " + "; ".join(notes)) if notes else "I have no saved notes about you."
    if tool_name == "save_note":
        return "Noted. I will remember that in future chats."
    if data.get("results"):
        top = data["results"][0]
        return f"Best match [{top['id']}]: " + " ".join(top["text"].split())[:220]
    if "subject" in data:
        return f"Ticket {data['ticket_id']} ({data['subject']}) is {data['status']}, priority {data['priority']}."
    if data.get("ok"):
        return data.get("message") or "Done."
    return "I could not find anything useful for that."


def _from_history(messages, ql):
    text = " ".join(text_of(m) for m in messages if not isinstance(m, SystemMessage))
    ids = re.findall(r"(?:EMP|TKT)-\d+", text)
    if "employee id" in ql or "my id" in ql:
        emp = [i for i in ids if i.startswith("EMP")]
        return f"Your employee id is {emp[0]}." if emp else "I don't know your employee id any more (it is not in what I can see)."
    if "first" in ql:
        tk = [i for i in ids if i.startswith("TKT")]
        return f"The first ticket we discussed was {tk[0]}." if tk else "I can't see the start of our chat any more."
    return "So far we discussed: " + ", ".join(dict.fromkeys(ids)) if ids else "We discussed a few IT questions."


def _offline_summary(prompt):
    ids = list(dict.fromkeys(re.findall(r"(?:EMP|TKT)-\d+", prompt)))
    return ("## SESSION INTENT\nUser is asking AskIT several IT helpdesk questions.\n## SUMMARY\n"
            f"Ids mentioned: {', '.join(ids) or 'none'}. Topics: tickets, VPN, passwords.\n## NEXT STEPS\nAnswer the next question.")


ROUTE_WORDS = {
    "Access": ["password", "locked", "login", "access", "mfa", "admin", "account", "permission"],
    "Network": ["vpn", "wifi", "wi-fi", "network", "internet", "connect", "809"],
    "Hardware": ["laptop", "screen", "monitor", "battery", "keyboard", "printer", "blue screen", "device", "phone"],
}


def _offline_route(text):
    tl = text.lower()
    scores = {r: sum(w in tl for w in words) for r, words in ROUTE_WORDS.items()}
    best = max(scores, key=scores.get)
    return best if scores[best] else "General"
